export const templates3d={blank3d:'3D playground',runner3d:'3D lane runner'};
export function make3DObject(kind='box',x=0,y=.5,z=0){const character=kind==='character';return{id:crypto.randomUUID(),name:character?'Character':kind[0].toUpperCase()+kind.slice(1),type:character?'player':kind==='ground'?'platform':kind==='coin'?'coin':kind==='hazard'?'hazard':'sprite',mesh:kind,x,y,z,w:character?.65:kind==='ground'?16:1,h:character?1.9:kind==='ground'?.3:1,depth:character?.65:kind==='ground'?120:1,color:character?'#2caee5':kind==='coin'?'#ffca35':kind==='hazard'?'#e95871':kind==='ground'?'#465266':'#9166d2',physics:true,body:character?'kinematic':kind==='coin'||kind==='hazard'?'trigger':'static',gravity:1,friction:.6,bounce:0,rotation:0,events:[],speed:6,jumpSpeed:8,animation3d:'auto'}}
export function populate3D(project){project.dimension='3d';project.gravity=1;project.width=960;project.height=540;project.variables={Score:0,Health:3,Jumps:0,Lane:1,Distance:0};project.swipeEvents=[{direction:'up',action:'jump',value:1},{direction:'down',action:'slide',value:1},{direction:'left',action:'switchlane',value:-1},{direction:'right',action:'switchlane',value:1}];project.objects=[];const add=(kind,x,y,z)=>{const o=make3DObject(kind,x,y,z);project.objects.push(o);return o};add('character',0,.98,0);add('ground',0,-.15,-40);if(project.template==='runner3d'){project.runner={enabled:true,speed:8,lanes:3,laneWidth:2.2};project.swipeEvents=[{direction:'up',action:'jump',value:1},{direction:'down',action:'slide',value:1},{direction:'left',action:'switchlane',value:-1},{direction:'right',action:'switchlane',value:1}];for(let i=0;i<12;i++){const o=add(i%3===0?'hazard':'coin',(i%3-1)*2.2,i%3===0?.45:1,-12-i*7);if(o.mesh==='coin'){o.w=o.h=o.depth=.5}else{o.w=1.5;o.h=.9;o.depth=1}}const gate=add('hazard',2.2,1.55,-35);gate.name='Slide under beam';gate.w=1.9;gate.h=.65;gate.depth=1;project.instructions='Swipe ↑ jump · ↓ slide · ← → change lanes. Keyboard: arrows or WASD.'}else{const box=add('box',3,1,-4);box.h=2;box.body='dynamic';add('sphere',-3,2,-3).body='dynamic';add('coin',0,1,-6)}project.ui=[{id:crypto.randomUUID(),type:'counter',text:'Coins',variable:'Score',x:3,y:4,w:22,h:9,color:'#202332',textColor:'#ffffff',fontSize:20,action:'none',value:1},{id:crypto.randomUUID(),type:'counter',text:'Health',variable:'Health',x:74,y:4,w:22,h:9,color:'#202332',textColor:'#ffffff',fontSize:20,action:'none',value:1}];return project}
